const refreshScanRunTaskCounters = `-- name: RefreshScanRunTaskCounters :one
WITH task_counts AS (
  SELECT
    count(*) FILTER (WHERE status = 'succeeded')::bigint AS completed_tasks,
    count(*) FILTER (WHERE status = 'failed')::bigint AS failed_tasks,
    count(*) FILTER (WHERE status IN ('pending', 'retryable', 'running'))::bigint AS active_tasks
  FROM scan_tasks
  WHERE scan_run_id = $1
)
UPDATE scan_runs r
SET completed_tasks = task_counts.completed_tasks,
    failed_tasks = task_counts.failed_tasks,
    status = CASE
      WHEN task_counts.active_tasks = 0 AND task_counts.failed_tasks > 0 THEN 'failed'
      WHEN task_counts.active_tasks = 0 THEN 'succeeded'
      ELSE r.status
    END,
    phase = CASE
      WHEN task_counts.active_tasks = 0 THEN 'finished'
      ELSE r.phase
    END,
    finished_at = CASE
      WHEN task_counts.active_tasks = 0 THEN COALESCE(r.finished_at, now())
      ELSE r.finished_at
    END,
    last_heartbeat_at = now()
FROM task_counts
WHERE r.id = $1
RETURNING r.id, r.nexus_instance_id, r.scan_type, r.repository_name, r.trigger_source, r.trigger_job_name, r.status, r.phase, r.started_at, r.finished_at, r.last_heartbeat_at, r.estimated_total_tasks, r.completed_tasks, r.failed_tasks, r.progress_percent, r.progress_confidence, r.cursor_before, r.cursor_after, r.stats, r.error_code, r.error_class, r.error_message, r.error_details
`

